def node_html(n):
    kind, label, name, pct, x, y = n
    if kind == 'estate':
        p = int(str(pct).replace('%',''))
        return f'<div class="node" style="left:{x}%;top:{y}%"><svg class="ring" viewBox="0 0 76 76" data-pct="{p}"><circle class="track" cx="38" cy="38" r="31"/><circle class="value" cx="38" cy="38" r="31" pathLength="100"/></svg><span class="ring-label">{escape(pct)}</span><div class="dot">{escape(label)}</div><b>{escape(name)}</b><small>接驳覆盖</small></div>'
    klass = 'node station' if kind == 'station' else 'node dest' if kind == 'dest' else 'node'
    return f'<div class="{klass}" style="left:{x}%;top:{y}%"><div class="dot">{escape(label)}</div><b>{escape(name)}</b>{"<small>目的地</small>" if kind == "dest" else "<small>公交站</small>" if kind == "station" else ""}</div>'

def page(d):
    nav = ''.join(f'<a class="pill" href="{p["slug"]}.html">{p["mode"].split(" · ")[0]}</a>' for p in PAGES)
    nodes = ''.join(node_html(n) for n in d['nodes'])
    rows = ''.join(f'<div class="row"><span>{escape(a)}</span><strong>{escape(b)}</strong><span>{escape(c)}</span></div>' for a,b,c in d['rows'])
    stats = ''.join(f'<div class="stat"><b>{escape(a)}</b><span>{escape(b)}</span></div>' for a,b in d['stats'])
    flow = ''.join(f'<div class="step"><em>{i}</em><h3>{escape(a)}</h3><p>{escape(b)}</p></div>' for i,(a,b) in enumerate(d['flow'],1))
    legend = '<div class="legend"><span><i class="g"></i>绿色=已覆盖</span><span><i class="a"></i>琥珀=接近上限</span><span><i class="r"></i>红色=需调整</span></div>'
    static_mark = '<span class="static-badge">静态演示 · 无需注册 · 不计入排行榜</span>' if d['slug'] in {'mode1', 'mode4'} else ''
    static_footer = ' · 不连接账号与排行榜' if d['slug'] in {'mode1', 'mode4'} else ''
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f6f4ee"><title>TransitLab HK · {escape(d['mode'])} · 独立展示页</title><style>{CSS}</style></head><body>
<header class="top"><a class="brand" href="index.html">TransitLab HK <small>STATIC DEMO</small></a><span class="sp"></span>{static_mark}<span class="lang">简中 / 繁中 / EN</span><a class="back" href="index.html">全部关卡</a></header>
<main class="wrap"><div class="eyebrow">{escape(d['mode'])} · MOBILE READY</div><section class="hero"><div><h1>{escape(d['title'])}</h1><p>{escape(d['lead'])}</p></div><aside class="hero-note"><b>{escape(d['note'])}</b>{escape(d['note_text'])}</aside></section>
<section class="layout"><div class="map"><div class="map-caption">{escape(d['map_label'])} · 数据示意</div><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M2 76 C24 58 25 34 48 52 S76 65 98 28" fill="none" stroke="#bdd4c2" stroke-width="1.2" stroke-dasharray="3 2"/><path d="M9 30 C28 46 45 40 65 26 S82 31 96 60" fill="none" stroke="#d8cba8" stroke-width=".9" stroke-dasharray="2 3"/><path d="M0 83 C28 74 42 80 68 70 S87 55 100 50" fill="none" stroke="#d9deda" stroke-width=".7"/></svg>{nodes}</div><aside class="aside"><div class="card"><h2>Live KPI · 本轮数据</h2><div class="statgrid">{stats}</div></div><div class="card"><h2>百分比对照</h2><div class="rows">{rows}</div><p style="margin-top:10px">环形进度以实际百分比绘制：100% 为整圈，50% 为半圈，80% 为五分之四圈。</p></div><div class="card"><h2>图例</h2>{legend}</div></aside></section>
<section class="flow">{flow}</section><footer class="footer"><span>独立静态展示页 · 可从 PPT 或手机直接打开{static_footer}</span><button class="pill" onclick="document.body.classList.toggle('focus')">突出显示比例</button></footer></main>
<script>document.querySelectorAll('.ring').forEach(function(svg){{var p=Math.max(0,Math.min(100,Number(svg.dataset.pct)||0));var c=svg.querySelector('.value');c.style.strokeDasharray=p+' '+(100-p);c.style.strokeDashoffset='0';}});</script></body></html>'''

for d in PAGES:
    (ROOT / f"{d['slug']}.html").write_text(page(d), encoding='utf-8')

index = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TransitLab HK · 独立关卡展示</title><style>'''+CSS+'''</style></head><body><header class="top"><a class="brand" href="index.html">TransitLab HK <small>STATIC DEMO</small></a><span class="sp"></span><span class="lang">简中 / 繁中 / EN</span></header><main class="wrap"><div class="eyebrow">现场备用入口 · 01–04</div><section class="hero"><div><h1>独立关卡展示页</h1><p>每个关卡都可以单独打开，适合手机或现场演示。页面保留主要数据流程，并将绿色圈和百分比严格对应。</p></div><aside class="hero-note"><b>推荐演示顺序</b>先看 01 车站与步行，再进入 05 大沙盘完成“改人口 → 划线 → 运行数据”。</aside></section><section class="flow">'''+''.join(f'<a class="step" href="{d["slug"]}.html"><em>{d["mode"].split(" · ")[0]}</em><h3>{escape(d["title"])}</h3><p>{escape(d["lead"][:95])}…</p></a>' for d in PAGES)+'''</section><footer class="footer"><span>demo-static/ · 无需后端即可打开</span><span><a class="pill" href="ring-verification.html">绿圈比例校验</a> <a class="pill" href="../mode5-sandbox/index.html">打开 05 大沙盘</a></span></footer></main></body></html>'''
(ROOT / 'index.html').write_text(index, encoding='utf-8')
(ROOT / 'README.md').write_text('''# TransitLab HK · 独立关卡展示页

这些页面是为现场演示准备的静态备用入口，每关可以单独打开，手机宽度下自动换成单列布局。页面中的绿色圆环以真实百分比绘制：100% 为整圈、50% 为半圈、80% 为 80% 圈。

- `index.html`：四关入口与演示顺序
- `mode1.html`：车站与步行，静态演示、无需注册、不计入排行榜
- `mode2.html`：地铁，展示线路、班次、预算
- `mode3.html`：道路拥堵，展示早高峰 V/C 与分流
- `mode4.html`：站旁开发，静态演示、无需注册、不计入排行榜
- `ring-verification.html`：校验 0/50/80/100% 与绿圈弧长对应关系

`mode1.html` 与 `mode4.html` 不读取或写入账号、排行榜，也不会发起网络请求；打开文件即可展示。所有绿圈都使用同一个百分比来源：100% 整圈、50% 半圈、80% 五分之四圈。原有 `mode1-bus` 至 `mode4-tod` 互动页面保持不变。
''', encoding='utf-8')

verify = f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TransitLab HK · 绿圈比例校验</title><style>{CSS}.verify{{max-width:760px;margin:0 auto;padding:28px 18px 48px}}.verify h1{{font:600 42px Georgia,serif;margin:8px 0}}.verify p{{color:var(--muted);line-height:1.7}}.checks{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}}.check{{background:#fff;border:1px solid var(--line);border-radius:16px;padding:13px;text-align:center;box-shadow:var(--shadow)}}.check .ring{{width:110px;height:110px;margin:4px auto 2px}}.check .ring-label{{position:static;display:block;transform:none;font-size:15px}}.formula{{padding:14px 16px;border:1px dashed #a9c8b3;border-radius:12px;background:#f5fbf6;color:#315e44;font-family:ui-monospace,monospace;font-size:12px;line-height:1.65}}@media(max-width:650px){{.checks{{grid-template-columns:repeat(2,1fr)}}.verify h1{{font-size:34px}}}}</style></head><body><header class="top"><a class="brand" href="index.html">TransitLab HK <small>RING CHECK</small></a><span class="sp"></span><a class="back" href="index.html">返回关卡</a></header><main class="verify"><div class="eyebrow">DATA ↔ VISUAL VERIFICATION</div><h1>绿圈和百分比一一对应</h1><p>这是现场备用校验页。环形进度的弧长使用同一个百分比数据源：0% 没有绿色弧线，50% 是半圈，80% 是五分之四圈，100% 才是整圈。</p><div class="checks">{''.join(f'<div class="check"><svg class="ring" viewBox="0 0 76 76" data-pct="{p}"><circle class="track" cx="38" cy="38" r="31"/><circle class="value" cx="38" cy="38" r="31" pathLength="100"/></svg><span class="ring-label">{p}%</span></div>' for p in (0,50,80,100))}</div><div class="formula">strokeDasharray = 百分比 + (100 − 百分比)<br>示例：50% → 50 50；80% → 80 20；100% → 100 0</div></main><script>document.querySelectorAll('.ring').forEach(function(svg){{var p=Math.max(0,Math.min(100,Number(svg.dataset.pct)||0));svg.querySelector('.value').style.strokeDasharray=p+' '+(100-p);}});</script></body></html>'''
(ROOT / 'ring-verification.html').write_text(verify, encoding='utf-8')
print('generated', len(PAGES)+1, 'pages in', ROOT)






